class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def minMovesToSort(nums):
    head = build(nums)
    n = 0
    pos = {}
    cur = head
    while cur:
        pos[cur.val] = n
        n += 1
        cur = cur.next
    if n == 0:
        return 0
    order = sorted(pos)
    best = run = 1
    for i in range(1, n):
        if pos[order[i]] > pos[order[i - 1]]:
            run += 1
        else:
            run = 1
        best = max(best, run)
    return n - best
